// ─────────────────────────────────────────────────────────────────────────────
// NÓ 3 — Validar mensagem + filtrar contexto do banco por relevância
//
// MELHORIA 1: separação clara do caminho de erro do banco (tratado no nó 2b)
// MELHORIA 2: filtragem inteligente — só envia ao Gemini o que é relevante
//             para a pergunta, mantendo o payload < ~80KB e economizando tokens
// ─────────────────────────────────────────────────────────────────────────────

const webhook = $('1. Receber Pergunta').first().json;
const body = webhook.body ?? webhook;
const mensagem = (body.mensagem || body.message || '').trim();

if (!mensagem) {
  return [{ json: { resposta: 'Envie uma mensagem no campo "mensagem".' } }];
}

const db = $input.first().json;

// ── Helpers ──────────────────────────────────────────────────────────────────

// Normaliza texto para busca sem acento e minúsculo
function norm(str) {
  return String(str || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

// Verifica se um objeto contém algum dos termos da pergunta
function match(obj, termos) {
  const texto = norm(JSON.stringify(obj));
  return termos.some(t => texto.includes(t));
}

// Extrai até N itens mais relevantes de um array pelo score de matches
function filtrar(arr, termos, limite) {
  if (!Array.isArray(arr) || arr.length === 0) return [];
  if (arr.length <= limite) return arr;

  const scored = arr.map(item => ({
    item,
    score: termos.filter(t => norm(JSON.stringify(item)).includes(t)).length,
  }));

  scored.sort((a, b) => b.score - a.score);

  // Sempre inclui os que tiveram pelo menos 1 match; complementa até o limite
  const comMatch = scored.filter(s => s.score > 0).map(s => s.item);
  const semMatch = scored.filter(s => s.score === 0).map(s => s.item);

  return [...comMatch, ...semMatch].slice(0, limite);
}

// ── Tokenização simples da pergunta ──────────────────────────────────────────
// Remove stopwords em pt-BR e mantém tokens com 3+ chars
const STOPWORDS = new Set([
  'de','do','da','dos','das','em','no','na','nos','nas','para','com',
  'por','que','como','qual','quais','quem','quando','onde','o','a',
  'os','as','um','uma','uns','umas','e','ou','se','mas','mais',
  'este','esta','esse','essa','isso','aquele','aquela','ele','ela',
  'meu','minha','seu','sua','nosso','nossa','foi','ser','ter','tem',
  'me','te','nos','lhe','lhes','ja','nao','sim','ainda','tambem',
]);

const termos = norm(mensagem)
  .split(/[\s,.:;!?()\[\]{}"']+/)
  .filter(t => t.length >= 3 && !STOPWORDS.has(t));

// ── Detectar intenção por categoria ─────────────────────────────────────────
const msg = norm(mensagem);

const quer = {
  cliente:    /client|cpf|email|comprador/.test(msg),
  veiculo:    /veiculo|carro|moto|placa|chassi|marca|modelo|ano/.test(msg),
  projeto:    /projeto|orcamento|previsao|categoria/.test(msg),
  mecanico:   /mecanic|especialidade|nivel|tecnic/.test(msg),
  servico:    /servico|hora|realiz|valor|categor/.test(msg),
  peca:       /peca|estoque|fabricante|origem|numero|tipo/.test(msg),
  fornecedor: /fornecedor|contato|fornec/.test(msg),
  uso:        /uso|vendid|quantidade|movimentad/.test(msg),
  historico:  /historic|status|km|quilometr|andamento/.test(msg),
  upgrade:    /upgrade|restomod|whp|kgfm|doador|adaptacao/.test(msg),
  inspecao:   /inspecao|inspecionar|result|observ|vistoria/.test(msg),
  analise:    /analise|analytic|relatorio|ranking|top|total|maior|menor|mais|menos/.test(msg),
};

// Se nenhuma categoria detectada, inclui tudo (pergunta genérica)
const algumDetectado = Object.values(quer).some(Boolean);
if (!algumDetectado) Object.keys(quer).forEach(k => quer[k] = true);

// ── Montar contexto filtrado ──────────────────────────────────────────────────
// Limites por entidade: reduz em ~70-90% o payload quando o banco está populado
const LIMITE = {
  padrao:  15,   // entidades principais quando relevantes
  pequeno:  8,   // entidades de suporte
  grande:  25,   // servicos/pecas (mais granulares)
};

const ctx = {};

if (quer.cliente)    ctx.clientes    = filtrar(db.clientes,    termos, LIMITE.padrao);
if (quer.veiculo)    ctx.veiculos    = filtrar(db.veiculos,    termos, LIMITE.padrao);
if (quer.projeto)    ctx.projetos    = filtrar(db.projetos,    termos, LIMITE.padrao);
if (quer.mecanico)   ctx.mecanicos   = filtrar(db.mecanicos,   termos, LIMITE.padrao);
if (quer.servico)    ctx.servicos    = filtrar(db.servicos,    termos, LIMITE.grande);
if (quer.peca)       ctx.pecas       = filtrar(db.pecas,       termos, LIMITE.grande);
if (quer.fornecedor) ctx.fornecedores = filtrar(db.fornecedores, termos, LIMITE.pequeno);
if (quer.uso)        ctx.uso_pecas   = filtrar(db.uso_pecas,   termos, LIMITE.grande);
if (quer.historico)  ctx.historicos_projeto = filtrar(db.historicos_projeto, termos, LIMITE.padrao);
if (quer.upgrade)    ctx.upgrades_restomod  = filtrar(db.upgrades_restomod,  termos, LIMITE.padrao);
if (quer.inspecao)   ctx.inspecoes   = filtrar(db.inspecoes,   termos, LIMITE.padrao);
if (quer.analise)    ctx.analises    = db.analises; // sempre completo (já é pequeno)

// Sempre inclui oficinas (referência em projetos/mecânicos)
ctx.oficinas = db.oficinas || [];

// ── Metadados de cobertura (debug e transparência) ───────────────────────────
const cobertura = {};
for (const [k, v] of Object.entries(ctx)) {
  const total = db[k]?.length ?? (k === 'analises' ? 1 : 0);
  if (Array.isArray(v)) cobertura[k] = `${v.length}/${total}`;
}

// ── Montar prompt final ───────────────────────────────────────────────────────
const contextoStr = JSON.stringify(ctx, null, 2);

const prompt = `Você é o assistente de análise do sistema Restomod-Core, plataforma de gestão de oficinas automotivas com foco em Restomod.

REGRAS:
- Use APENAS os dados JSON abaixo, lidos diretamente do banco PostgreSQL.
- Entidades disponíveis: clientes, oficinas, veículos, projetos, mecânicos, serviços, peças, fornecedores, uso de peças, histórico de projetos, upgrades restomod, inspeções e análises agregadas.
- Os dados foram pré-filtrados por relevância para a pergunta. Se a informação não estiver presente, informe que pode estar fora do recorte e sugira reformular a pergunta com mais detalhes.
- Se listas estiverem vazias, o banco pode não estar populado (botão "Carregar Banco" no dashboard).
- Cruze dados quando necessário (ex.: veículo → cliente → projetos → serviços).
- Responda em português, claro e objetivo.
- Valores monetários em R$ com formato brasileiro (vírgula decimal, ponto milhar).
- Se for uma análise ou ranking, formate em lista ou tabela Markdown.

DADOS DO BANCO (filtro aplicado: ${JSON.stringify(cobertura)}):
${contextoStr}

PERGUNTA:
${mensagem}`;

return [{ json: { prompt, mensagem } }];

const gemini = $input.first().json;

if (gemini.error) {
  const msg = gemini.error.message || JSON.stringify(gemini.error);
  return [{ json: { resposta: `Erro na API Gemini: ${msg}` } }];
}

const texto = gemini.candidates?.[0]?.content?.parts?.[0]?.text;
if (!texto) {
  return [{ json: { resposta: 'Gemini não retornou texto. Verifique a GEMINI_API_KEY e o modelo.' } }];
}

return [{ json: { resposta: texto.trim() } }];
